// The actor and its template already exist. Failed suspension leaves the actor
// running, so the test isolates error propagation rather than provisioning.
type suspendFailureControl struct {
	ateapipb.UnimplementedControlServer
	suspendError error
	suspendCalls atomic.Int32
	actorState   atomic.Int32
}

func (m *suspendFailureControl) CreateAtespace(context.Context, *ateapipb.CreateAtespaceRequest) (*ateapipb.Atespace, error) {
	return nil, status.Error(codes.AlreadyExists, "atespace exists")
}

func (m *suspendFailureControl) GetActorTemplate(_ context.Context, req *ateapipb.GetActorTemplateRequest) (*ateapipb.ActorTemplate, error) {
	ref := req.GetActorTemplate()
	return &ateapipb.ActorTemplate{Metadata: &ateapipb.ResourceMetadata{
		Name: ref.GetName(), Atespace: ref.GetAtespace(),
	}}, nil
}

func (m *suspendFailureControl) CreateActor(context.Context, *ateapipb.CreateActorRequest) (*ateapipb.Actor, error) {
	return nil, status.Error(codes.AlreadyExists, "actor exists")
}

func (m *suspendFailureControl) GetActor(_ context.Context, req *ateapipb.GetActorRequest) (*ateapipb.Actor, error) {
	ref := req.GetActor()
	return &ateapipb.Actor{
		Metadata: &ateapipb.ResourceMetadata{Name: ref.GetName(), Atespace: ref.GetAtespace()},
		Status: &ateapipb.ActorStatus{
			State:            ateapipb.ActorState(m.actorState.Load()),
			WorkerAssignment: &ateapipb.WorkerAssignment{WorkerPodIp: "10.244.1.42"},
		},
	}, nil
}

func (m *suspendFailureControl) SuspendActor(context.Context, *ateapipb.SuspendActorRequest) (*ateapipb.SuspendActorResponse, error) {
	m.suspendCalls.Add(1)
	if m.suspendError != nil {
		return nil, m.suspendError
	}
	m.actorState.Store(int32(ateapipb.ActorState_ACTOR_STATE_SUSPENDED))
	return &ateapipb.SuspendActorResponse{}, nil
}

func TestSuspendTask_SubstrateResult(t *testing.T) {
	for _, tc := range []struct {
		name string
		code codes.Code
	}{
		{name: "success", code: codes.OK},
		{name: "unavailable", code: codes.Unavailable},
		{name: "permission_denied", code: codes.PermissionDenied},
	} {
		t.Run(tc.name, func(t *testing.T) {
			ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			defer cancel()
			mock := &suspendFailureControl{}
			mock.actorState.Store(int32(ateapipb.ActorState_ACTOR_STATE_RUNNING))
			if tc.code != codes.OK {
				mock.suspendError = status.Error(tc.code, "injected suspension failure")
			}
			dialOptions := func(listener *bufconn.Listener) []grpc.DialOption {
				return []grpc.DialOption{
					grpc.WithTransportCredentials(insecure.NewCredentials()),
					grpc.WithContextDialer(func(ctx context.Context, _ string) (net.Conn, error) {
						return listener.DialContext(ctx)
					}),
				}
			}
			substrateListener := bufconn.Listen(1024 * 1024)
			defer substrateListener.Close()
			substrateServer := grpc.NewServer()
			ateapipb.RegisterControlServer(substrateServer, mock)
			go substrateServer.Serve(substrateListener)
			defer substrateServer.Stop()
			substrateClient, err := substrate.NewClient("passthrough:///substrate", dialOptions(substrateListener)...)
			if err != nil {
				t.Fatal(err)
			}
			defer substrateClient.Close()
			reconciler := controller.NewTaskReconciler(substrateClient, "test-template", "ax-system")
			reconciler.SecretResolver = func(context.Context, string, string, string) (string, error) {
				return "", nil
			}
			store := memory.NewStore()
			defer store.Close()
			if err := store.SaveTask(ctx, &v1alpha1.Task{
				Metadata: &v1alpha1.ObjectMeta{Name: "suspend-repro", Atespace: "default"},
				Spec:     &v1alpha1.TaskSpec{Image: "example.invalid/runner@sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"},
				Status: &v1alpha1.TaskStatus{
					Phase: "Running", Actor: "suspend-repro", Id: "existing-task-id", WorkerIp: "10.244.1.42",
					Conditions: []*v1alpha1.Condition{{Type: "Ready", Status: "True", Reason: "TaskRunning"}},
				},
			}); err != nil {
				t.Fatal(err)
			}
			axServer := server.NewServer(store, server.Options{Reconciler: reconciler})
			axListener := bufconn.Listen(1024 * 1024)
			defer axListener.Close()
			go axServer.GRPCServer().Serve(axListener)
			defer axServer.GRPCServer().Stop()
			axConn, err := grpc.NewClient("passthrough:///ax", dialOptions(axListener)...)
			if err != nil {
				t.Fatal(err)
			}
			defer axConn.Close()
			response, rpcErr := v1alpha1.NewAXClient(axConn).SuspendTask(ctx, &v1alpha1.SuspendTaskRequest{
				Atespace: "default", Name: "suspend-repro",
			})
			stored, err := store.GetTask(ctx, "default", "suspend-repro")
			if err != nil {
				t.Fatal(err)
			}
			actorState := ateapipb.ActorState(mock.actorState.Load())
			t.Logf("substrate_code=%s api_code=%s response_phase=%q stored_phase=%q stored_worker_ip=%q actor_state=%s suspend_calls=%d",
				tc.code, status.Code(rpcErr), response.GetStatus().GetPhase(), stored.GetStatus().GetPhase(),
				stored.GetStatus().GetWorkerIp(), actorState, mock.suspendCalls.Load())
			if mock.suspendCalls.Load() != 1 {
				t.Fatalf("SuspendActor calls = %d, want 1", mock.suspendCalls.Load())
			}
			if tc.code == codes.OK {
				if rpcErr != nil || stored.GetStatus().GetPhase() != "Suspended" || stored.GetStatus().GetWorkerIp() != "" {
					t.Fatalf("successful suspension: error=%v, status=%v", rpcErr, stored.GetStatus())
				}
				if actorState != ateapipb.ActorState_ACTOR_STATE_SUSPENDED {
					t.Fatalf("successful suspension left actor in %s", actorState)
				}
				return
			}
			if actorState != ateapipb.ActorState_ACTOR_STATE_RUNNING {
				t.Fatalf("fault injection changed actor state to %s", actorState)
			}
			if rpcErr == nil {
				t.Error("SuspendTask returned success after Substrate rejected suspension")
			}
			if stored.GetStatus().GetPhase() != "Running" {
				t.Errorf("stored phase = %q, want Running after rejected suspension", stored.GetStatus().GetPhase())
			}
			if stored.GetStatus().GetWorkerIp() != "10.244.1.42" {
				t.Errorf("stored worker IP = %q, want original worker IP", stored.GetStatus().GetWorkerIp())
			}
			for _, condition := range stored.GetStatus().GetConditions() {
				if condition.GetReason() == "TaskSuspended" {
					t.Error("stored condition reports TaskSuspended after rejected suspension")
				}
			}
		})
	}
}
