+// cleanupSubstrate exercises real deletion reconciliation against a busy or
+// failing Substrate API, including a lease longer than the old retry window.
+type cleanupSubstrate struct {
+	ateapipb.UnimplementedControlServer
+	mu            sync.Mutex
+	busyUntil     time.Time
+	deleteErr     error
+	listErr       error
+	blockList     bool
+	blockDelete   bool
+	alreadyGone   bool
+	templates     map[string]bool
+	deleteCalls   int
+	deadlines     []time.Time
+	deleteStarted chan struct{}
+}
+
+func (s *cleanupSubstrate) DeleteActor(context.Context, *ateapipb.DeleteActorRequest) (*ateapipb.Actor, error) {
+	return nil, status.Error(codes.NotFound, "actor already deleted")
+}
+
+func (s *cleanupSubstrate) ListActorTemplates(ctx context.Context, _ *ateapipb.ListActorTemplatesRequest) (*ateapipb.ListActorTemplatesResponse, error) {
+	s.mu.Lock()
+	if deadline, ok := ctx.Deadline(); ok {
+		s.deadlines = append(s.deadlines, deadline)
+	} else {
+		s.deadlines = append(s.deadlines, time.Time{})
+	}
+	block, listErr := s.blockList, s.listErr
+	resp := &ateapipb.ListActorTemplatesResponse{}
+	for name := range s.templates {
+		resp.ActorTemplates = append(resp.ActorTemplates, &ateapipb.ActorTemplate{
+			Metadata: &ateapipb.ResourceMetadata{Name: name},
+		})
+	}
+	s.mu.Unlock()
+	if block {
+		<-ctx.Done()
+		return nil, status.FromContextError(ctx.Err()).Err()
+	}
+	return resp, listErr
+}
+
+func (s *cleanupSubstrate) DeleteActorTemplate(ctx context.Context, req *ateapipb.DeleteActorTemplateRequest) (*ateapipb.ActorTemplate, error) {
+	s.mu.Lock()
+	s.deleteCalls++
+	if s.deleteCalls == 1 {
+		close(s.deleteStarted)
+	}
+	if deadline, ok := ctx.Deadline(); ok {
+		s.deadlines = append(s.deadlines, deadline)
+	} else {
+		s.deadlines = append(s.deadlines, time.Time{})
+	}
+	block, deleteErr := s.blockDelete, s.deleteErr
+	if deleteErr == nil && time.Now().Before(s.busyUntil) {
+		deleteErr = status.Error(codes.Aborted, "another operation is in progress for this ActorTemplate")
+	}
+	if deleteErr == nil && !block {
+		delete(s.templates, req.GetActorTemplate().GetName())
+		if s.alreadyGone {
+			deleteErr = status.Error(codes.NotFound, "template already deleted")
+		}
+	}
+	s.mu.Unlock()
+	if block {
+		<-ctx.Done()
+		return nil, status.FromContextError(ctx.Err()).Err()
+	}
+	return &ateapipb.ActorTemplate{}, deleteErr
+}
